{
  "explanation": "The discriminant D = b² − 4ac of a quadratic ax² + bx + c tells you how many times the parabola crosses the x-axis. When D > 0 there are two distinct real roots; when D = 0 the parabola just touches the axis at one repeated root; when D < 0 the parabola stays entirely above or below the axis and there are no real roots.",
  "manimCode": "const ax = new Axes({
  xRange: [-5, 5, 1],
  yRange: [-6, 6, 2],
  xLength: 9,
  yLength: 5.5,
  tips: false
});
ax.moveTo([0, 0.3, 0]);
scene.add(ax);

let a = 1;
let b = -1;
let c = -2;

function disc() {
  return b * b - 4 * a * c;
}

function roots() {
  const D = disc();
  if (D < 0 || Math.abs(a) < 1e-9) return [];
  const s = Math.sqrt(D);
  if (D === 0) return [-b / (2 * a)];
  return [(-b - s) / (2 * a), (-b + s) / (2 * a)];
}

let curve = ax.plot(x => a * x * x + b * x + c, { color: BLUE, xRange: [-5, 5] });
scene.add(curve);

const rootDots = [];
function clearDots() {
  while (rootDots.length) {
    const d = rootDots.pop();
    scene.remove(d);
  }
}
function placeDots() {
  clearDots();
  const rs = roots();
  for (const r of rs) {
    if (r < -5 || r > 5) continue;
    const d = new Dot({ point: ax.c2p(r, 0), color: YELLOW });
    d.scale(1.2);
    scene.add(d);
    rootDots.push(d);
  }
}
placeDots();

let statusTex = null;
async function updateStatus() {
  const D = disc();
  let latex;
  let col;
  if (D > 1e-9) {
    latex = 'D = b^2 - 4ac > 0 \\rightarrow 2 \\text{ real roots}';
    col = GREEN;
  } else if (D < -1e-9) {
    latex = 'D = b^2 - 4ac < 0 \\rightarrow 0 \\text{ real roots}';
    col = RED;
  } else {
    latex = 'D = b^2 - 4ac = 0 \\rightarrow 1 \\text{ real root}';
    col = YELLOW;
  }
  if (statusTex) scene.remove(statusTex);
  statusTex = new MathTex({ latex: latex, color: col, fontSize: 28 });
  await statusTex.waitForRender();
  statusTex.moveTo([0, -3.4, 0]);
  scene.add(statusTex);
}
await updateStatus();

let discLabel = null;
async function updateDiscLabel() {
  const D = disc();
  const rounded = Math.round(D * 100) / 100;
  if (discLabel) scene.remove(discLabel);
  discLabel = new MathTex({
    latex: `D = ${rounded}`,
    color: WHITE,
    fontSize: 32
  });
  await discLabel.waitForRender();
  discLabel.toCorner(UL);
  discLabel.shift(scaleVec(0.3, DOWN));
  scene.add(discLabel);
}
await updateDiscLabel();

let eqLabel = null;
async function updateEq() {
  const fa = Math.round(a * 100) / 100;
  const fb = Math.round(b * 100) / 100;
  const fc = Math.round(c * 100) / 100;
  const bs = fb >= 0 ? `+ ${fb}` : `- ${Math.abs(fb)}`;
  const cs = fc >= 0 ? `+ ${fc}` : `- ${Math.abs(fc)}`;
  if (eqLabel) scene.remove(eqLabel);
  eqLabel = new MathTex({
    latex: `y = ${fa}x^2 ${bs}x ${cs}`,
    color: BLUE_B,
    fontSize: 26
  });
  await eqLabel.waitForRender();
  eqLabel.toCorner(UR);
  eqLabel.shift(scaleVec(0.3, DOWN));
  scene.add(eqLabel);
}
await updateEq();

function rebuildCurve() {
  scene.remove(curve);
  curve = ax.plot(x => a * x * x + b * x + c, { color: BLUE, xRange: [-5, 5] });
  scene.add(curve);
  placeDots();
}

const controls = new Controls(scene, { position: 'bottom-right', width: 260 });
controls.addSlider({
  label: 'a',
  min: -2,
  max: 2,
  value: a,
  step: 0.1,
  onChange: async (val) => {
    a = val === 0 ? 0.1 : val;
    rebuildCurve();
    await updateStatus();
    await updateDiscLabel();
    await updateEq();
  }
});
controls.addSlider({
  label: 'b',
  min: -5,
  max: 5,
  value: b,
  step: 0.1,
  onChange: async (val) => {
    b = val;
    rebuildCurve();
    await updateStatus();
    await updateDiscLabel();
    await updateEq();
  }
});
controls.addSlider({
  label: 'c',
  min: -5,
  max: 5,
  value: c,
  step: 0.1,
  onChange: async (val) => {
    c = val;
    rebuildCurve();
    await updateStatus();
    await updateDiscLabel();
    await updateEq();
  }
});
controls.addButton({
  label: 'Two roots (D>0)',
  onClick: async () => {
    a = 1; b = -1; c = -2;
    rebuildCurve();
    await updateStatus();
    await updateDiscLabel();
    await updateEq();
  }
});
controls.addButton({
  label: 'One root (D=0)',
  onClick: async () => {
    a = 1; b = -4; c = 4;
    rebuildCurve();
    await updateStatus();
    await updateDiscLabel();
    await updateEq();
  }
});
controls.addButton({
  label: 'No roots (D<0)',
  onClick: async () => {
    a = 1; b = 0; c = 2;
    rebuildCurve();
    await updateStatus();
    await updateDiscLabel();
    await updateEq();
  }
});

await scene.wait(999999);"
